# Properties and case mappings of every code point.
try: print('sum(1 for c in map(chr, range(0x110000)) if c.isdecimal()) =>', sum(1 for c in map(chr, range(0x110000)) if c.isdecimal()))
except Exception as _pe: print('<!' + type(_pe).__name__ + ": " + str(_pe) + '> in: sum(1 for c in map(chr, range(0x110000)) if c.isdecimal())')
